<template>
  <app-layout>
    <template #header><div><h2 class="font-semibold text-xl text-gray-800">Fee and Cost Classification</h2><p class="mt-1 text-sm text-gray-600">Classify imported fee and cost lines, then have someone else review them before the EIR is calculated</p></div></template>
    <template #actions><div v-if="view === 'lines'" class="flex gap-2"><Link :href="route('eir-intake.index', { type: 'fees' })" class="primary-btn whitespace-nowrap">Import fees</Link><button v-if="canClassify" @click="rematch" class="secondary-btn whitespace-nowrap">Re-apply rules to pending lines</button></div></template>
    <div class="w-full space-y-6">
      <KpiRow :cards="cards" />
      <!-- One tab row (navigation review of 15 October 2026): the first tab is the page's work, the lines
           being classified; then the checks on the fees, one tab each: the postings held for a loan, the
           sources that disagree, and the fees against the GL. -->
      <PageTabs v-model="view" :tabs="viewTabs" query="tab" />
      <template v-if="view === 'lines'">
      <div class="flex flex-col gap-1 rounded-lg border border-gray-200 bg-white px-4 py-2 text-xs text-gray-600 md:flex-row md:items-center md:gap-3">
        <span class="font-semibold text-gray-900">Accounting rulebook</span>
        <span>{{ ruleCoverage.approved_rules }} approved rule(s)<span v-if="ruleCoverage.draft_rules">, {{ ruleCoverage.draft_rules }} awaiting approval</span>.
          <template v-if="ruleCoverage.pending">{{ ruleCoverage.pending_matched }} of {{ ruleCoverage.pending }} pending line(s) carry a matched rule.</template><template v-else>No pending lines.</template></span>
        <span v-if="unmatchedPending > 0" class="text-amber-700">{{ unmatchedPending }} pending line(s) have no matched rule: re-apply after approving rules, or classify them manually.</span>
      </div>
      <div class="maiic-filterbar"><div class="grid grid-cols-1 md:grid-cols-4 gap-3 items-end"><label class="block"><span class="maiic-flabel">Contract or account</span><input v-model="filter.contract_id" class="form-input" placeholder="Part of the number" @keyup.enter="applyFilters"></label><label class="block"><span class="maiic-flabel">Status</span><select v-model="filter.status" class="form-input"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{ statusLabel(s) }}</option></select></label><label class="block"><span class="maiic-flabel">Fee or cost type</span><select v-model="filter.fee_type" class="form-input capitalize"><option value="">All types</option><option v-for="t in feeTypes" :key="t" :value="t">{{ t }}</option></select></label><div><button @click="applyFilters" class="primary-btn justify-center w-full md:w-auto">Apply filters</button></div></div></div>
      <!-- the buttons act on the fee lines: below the cards and the tabs, at the top right of the table -->
      <div data-actions-anchor></div>
      <div v-if="selected.length" class="bg-maiic-50 border border-maiic-200 rounded-lg p-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div class="font-medium text-maiic-900">{{selected.length}} selected line(s)<span v-if="selectedMatched < selected.length" class="ml-2 text-xs font-normal text-amber-700">{{ selected.length - selectedMatched }} without a matched rule</span></div><div class="flex flex-wrap gap-2"><button @click="openClassify('rule')" class="primary-btn" :disabled="selectedMatched===0">Classify using each line's rule</button><button @click="openClassify('manual')" class="secondary-btn">Classify manually</button><button @click="showReviewModal=true" class="secondary-btn">Review/approve</button><button @click="openReturn" class="secondary-btn" :disabled="selectedReturnable===0" :title="selectedReturnable===0 ? 'Select classified or reviewed lines' : 'Send them back to classification with the reason; a second person reviews them again'">Return to classification</button></div></div>
      <div class="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden"><div class="overflow-x-auto"><table class="min-w-full divide-y divide-gray-200">
        <thead><tr><th class="th"><input v-if="canClassify" type="checkbox" :checked="allSelected" @change="toggleAll"></th><th class="th">Contract / reference</th><th class="th">Fee or cost</th><th class="th text-right">Amount</th><th class="th">Rule suggestion</th><th class="th">Decision</th><th class="th">Status</th></tr></thead>
        <tbody class="divide-y divide-gray-200"><tr v-for="fee in fees.data" :key="fee.id" class="hover:bg-maiic-50"><td class="td"><input v-if="canClassify" type="checkbox" :value="fee.id" v-model="selected" :title="fee.classification_status==='REVIEWED' ? 'A reviewed line can only be returned to classification' : ''"></td><td class="td"><div class="font-medium text-gray-900">{{ fee.contract_id }}</div><div class="text-xs text-gray-500">{{ fee.source_reference || fee.external_transaction_id || 'No source reference' }}</div><span v-if="fee.superseded_by_source" class="maiic-badge maiic-badge-grey mt-1" :title="'Superseded ' + (fee.superseded_at || '') + ': kept and shown, left out of the EIR (one fee, one source)'">Superseded by {{ fee.superseded_by_source }}</span></td><td class="td"><div class="capitalize font-medium">{{ fee.fee_type }}</div><div class="text-xs text-gray-500">{{ fee.description || 'No description' }} · {{ fee.cashflow_direction || 'direction pending' }}</div></td><td class="td font-medium text-right tabular-nums whitespace-nowrap">{{ money(fee.amount) }} <span class="text-xs text-gray-500">{{ fee.currency }}</span></td><td class="td"><template v-if="fee.suggested_rule"><div class="text-sm">{{ fee.suggested_rule.name }}</div><span :class="fee.suggested_integral ? 'badge-green':'badge-gray'">{{ fee.suggested_integral ? 'Integral':'Non-integral' }}</span></template><span v-else class="text-xs text-gray-400">No matching rule</span></td><td class="td"><span v-if="fee.integral!==null" :class="fee.integral ? 'badge-green':'badge-gray'">{{ fee.integral ? 'Integral':'Non-integral' }}</span><div class="text-xs text-gray-500 mt-1 max-w-xs">{{ fee.classification_reason }}</div></td><td class="td"><span :class="statusClass(fee.classification_status)">{{ statusLabel(fee.classification_status) }}</span></td></tr><tr v-if="!fees.data.length"><td colspan="7" class="p-10 text-center text-sm text-gray-500"><template v-if="filter.status || filter.fee_type || filter.contract_id">No fee or cost lines match these filters. Clear a filter to see more.</template><template v-else>No fee or cost lines have been imported yet. Load fees through <Link :href="route('eir-intake.index')" class="font-semibold text-maiic-700 underline">EIR Data Intake</Link>, then classify them here.</template></td></tr></tbody>
      </table></div><div v-if="fees.links && fees.links.length > 3" class="px-4 pb-4 border-t"><Pagination :links="fees.links" /></div></div>
      </template>
      <FeeSourcesPanel v-else-if="view === 'held' || view === 'differences'" :view="view" :held="heldGlFees" :differences="sourceDifferences" :can-govern="canGovern" />
      <FeeGlReconciliation v-else :report="glReconciliation" :can-govern="canGovern" />
    </div>
    <jet-dialog-modal :show="showClassifyModal" @close="closeClassify"><template #title>{{ decision.mode==='rule' ? 'Classify by rule' : 'Classify manually' }}, {{selected.length}} line(s)</template><template #content><div class="space-y-4"><div v-if="decision.mode==='rule'" class="rounded-md border border-maiic-200 bg-maiic-50 p-3 text-sm text-maiic-900">Each line takes the treatment from its own matched rule, so a mixed selection resolves correctly in one action.<div class="mt-1 text-xs">{{ selectedMatched }} of {{ selected.length }} selected line(s) will be classified.<span v-if="selected.length - selectedMatched > 0"> The remaining {{ selected.length - selectedMatched }} have no matched rule and will be skipped, not guessed.</span></div></div><label v-if="decision.mode==='manual'" class="block text-sm font-medium text-gray-700">EIR treatment<select v-model="decision.integral" class="form-input mt-1"><option :value="null">Choose treatment</option><option :value="true">Integral - include in EIR</option><option :value="false">Non-integral - exclude</option></select></label><label v-if="decision.mode==='manual'" class="block text-sm font-medium text-gray-700">Accounting rule<select v-model="decision.accounting_rule_id" class="form-input mt-1"><option value="">No linked rule</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label v-if="missingDirection" class="block text-sm font-medium text-gray-700">Cash-flow direction for the {{ missingDirection }} line(s) loaded without one<select v-model="decision.cashflow_direction" class="form-input mt-1"><option value="">Leave blank (the line cannot enter the EIR)</option><option value="RECEIVED">Received: a fee charged to the borrower</option><option value="PAID">Paid: a cost MAIIC paid</option></select></label><label class="block text-sm font-medium text-gray-700">Accounting reason<textarea v-model="decision.reason" rows="3" class="form-input mt-1" :placeholder="decision.mode==='rule' ? 'e.g. Applied the approved rulebook following the December fee delivery.' : ''"></textarea></label><p v-if="localError||Object.keys(errors).length" class="text-sm text-red-700">{{localError||Object.values(errors)[0]}}</p></div></template><template #footer><button @click="closeClassify" class="secondary-btn mr-2">Cancel</button><button @click="classify" class="primary-btn">Save classification</button></template></jet-dialog-modal>
    <jet-dialog-modal :show="showReviewModal" @close="showReviewModal=false"><template #title>Approve classifications</template><template #content><p class="text-sm text-gray-700">Approve the classifications for <strong>{{selected.length}}</strong> selected line(s)? You cannot review decisions that you classified yourself.</p><p v-if="Object.keys(errors).length" class="mt-3 text-sm text-red-700">{{Object.values(errors)[0]}}</p></template><template #footer><button @click="showReviewModal=false" class="secondary-btn mr-2">Cancel</button><button @click="review" class="primary-btn">Approve classifications</button></template></jet-dialog-modal>
    <jet-dialog-modal :show="showReturnModal" @close="showReturnModal=false"><template #title>Return to classification, {{ selectedReturnable }} line(s)</template><template #content><p class="text-sm text-gray-700 dark:text-slate-300">The selected classified or reviewed lines go back to Pending. They are classified again (stating any missing field, such as the cash-flow direction) and a second person reviews them. A line of a contract whose original EIR is locked cannot be returned until that EIR is reopened.</p><label class="mt-3 block text-sm font-medium text-gray-700 dark:text-slate-300">Reason<textarea v-model="returnReason" rows="3" class="form-input mt-1" placeholder="e.g. Reviewed without a cash-flow direction; the LOS charge is received from the borrower."></textarea></label><p v-if="localError||Object.keys(errors).length" class="mt-2 text-sm text-red-700 dark:text-red-300">{{localError||Object.values(errors)[0]}}</p></template><template #footer><button @click="showReturnModal=false" class="secondary-btn mr-2">Cancel</button><button @click="returnLines" class="primary-btn">Return to classification</button></template></jet-dialog-modal>
    <teleport to="head"><title>EIR Fee Classification</title></teleport>
  </app-layout>
</template>
<script>
import AppLayout from '@/Layouts/AppLayout.vue'
import FeeGlReconciliation from '@/Components/Eir/FeeGlReconciliation.vue'
import FeeSourcesPanel from '@/Components/Eir/FeeSourcesPanel.vue'
import JetDialogModal from '@/Jetstream/DialogModal.vue'
import { Link } from '@inertiajs/vue3'
import KpiRow from '@/Components/Maiic/KpiRow.vue'
import PageTabs from '@/Components/Maiic/PageTabs.vue'
export default { components:{AppLayout,JetDialogModal,Link,KpiRow,FeeGlReconciliation,FeeSourcesPanel,PageTabs}, props:{fees:Object,rules:Array,filters:Object,summary:Object,glReconciliation:{type:Object,default:null},heldGlFees:{type:Array,default:()=>[]},sourceDifferences:{type:Array,default:()=>[]},canClassify:{type:Boolean,default:true},canGovern:{type:Boolean,default:false},ruleCoverage:{type:Object,default:()=>({pending:0,pending_matched:0,approved_rules:0,draft_rules:0})},errors:{type:Object,default:()=>({})}}, data(){return{view:'lines',showClassifyModal:false,showReviewModal:false,showReturnModal:false,returnReason:'',statuses:['PENDING','CLASSIFIED','REVIEWED','REJECTED'],feeTypes:['arrangement','legal','appraisal','default','levy','other'],selected:[],filter:{status:this.filters.status||'',fee_type:this.filters.fee_type||'',contract_id:this.filters.contract_id||''},decision:{mode:'manual',integral:null,accounting_rule_id:'',reason:'',cashflow_direction:''},localError:null}},computed:{viewTabs(){return[{key:'lines',label:'Fee lines',count:this.fees.total??null},{key:'held',label:'Held GL fee lines',count:this.heldGlFees.length},{key:'differences',label:'Source differences',count:this.sourceDifferences.length},{key:'gl',label:'Fees against the GL'}]},selectedReturnable(){const ids=new Set(this.selected);return (this.fees.data||[]).filter(f=>ids.has(f.id)&&['CLASSIFIED','REVIEWED'].includes(f.classification_status)).length},missingDirection(){const ids=new Set(this.selected);return (this.fees.data||[]).filter(f=>ids.has(f.id)&&!f.cashflow_direction).length},cards(){return this.statuses.map(st=>({label:this.statusLabel(st)+' lines',value:Number(this.summary[st]?.line_count||0),sub:this.money(this.summary[st]?.total_amount||0),accent:st==='REVIEWED'?'#15803d':st==='REJECTED'?'#dc2626':st==='PENDING'?'#d97706':'#0f766e'}))},allSelected(){return this.fees.data.length>0&&this.fees.data.filter(f=>f.classification_status!=='REVIEWED').every(f=>this.selected.includes(f.id))},unmatchedPending(){return Math.max(0,(this.ruleCoverage.pending||0)-(this.ruleCoverage.pending_matched||0))},selectedMatched(){return this.fees.data.filter(f=>this.selected.includes(f.id)&&f.suggested_rule_id!==null&&f.suggested_rule_id!==undefined).length}},methods:{statusLabel(st){return {PENDING:'Pending',CLASSIFIED:'Classified',REVIEWED:'Reviewed',REJECTED:'Rejected'}[st]||st},money(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})},statusClass(s){return s==='REVIEWED'?'badge-green':s==='CLASSIFIED'?'badge-blue':s==='REJECTED'?'badge-red':'badge-yellow'},toggleAll(e){this.selected=e.target.checked?this.fees.data.filter(f=>f.classification_status!=='REVIEWED').map(f=>f.id):[]},applyFilters(){this.$inertia.get(this.route('eir-fee-classification.index'),this.filter,{preserveState:true})},go(url){if(url)this.$inertia.get(url,{}, {preserveState:true})},rematch(){this.$inertia.post(this.route('eir-fee-classification.rematch'),{},{preserveScroll:true})},openClassify(mode){this.decision.mode=mode;this.localError=null;this.showClassifyModal=true},closeClassify(){this.showClassifyModal=false;this.localError=null},classify(){this.localError=null;if(!this.decision.reason.trim()){this.localError='Enter the accounting reason.';return}if(this.decision.mode==='manual'&&this.decision.integral===null){this.localError='Choose a treatment.';return}this.$inertia.post(this.route('eir-fee-classification.classify'),{fee_ids:this.selected,...this.decision},{onSuccess:()=>{this.showClassifyModal=false;this.selected=[];this.decision={mode:'manual',integral:null,accounting_rule_id:'',reason:'',cashflow_direction:''}}})},openReturn(){this.localError=null;this.returnReason='';this.showReturnModal=true},returnLines(){this.localError=null;if(this.returnReason.trim().length<5){this.localError='Enter the reason.';return}this.$inertia.post(this.route('eir-fee-classification.return'),{fee_ids:this.selected,reason:this.returnReason},{preserveScroll:true,onSuccess:()=>{this.showReturnModal=false;this.selected=[]}})},review(){this.$inertia.post(this.route('eir-fee-classification.review'),{fee_ids:this.selected},{onSuccess:()=>{this.showReviewModal=false;this.selected=[]}})}}
}
</script>
<style scoped>
.form-input{@apply block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-maiic-500}
</style>
